@@ -0,0 +1,25 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { stockValue } from "../src/domain/reports.js";
+import { fresh } from "./helpers.js";
+
+test("stock value rounds each item line half up before summing the total", () => {
+  const store = fresh();
+  store.data.items = [
+    { id: 1, name: "Flour", unit: "kg", priceCents: 1 },
+    { id: 2, name: "Rice", unit: "kg", priceCents: 1 },
+  ];
+  store.data.batches = [
+    { id: 1, itemId: 1, qty: 0.25 },
+    { id: 2, itemId: 1, qty: 0.25 },
+    { id: 3, itemId: 2, qty: 0.5 },
+  ];
+
+  const report = stockValue(store);
+  assert.deepEqual(report.lines, [
+    { itemId: 1, name: "Flour", qty: 0.5, valueCents: 1 },
+    { itemId: 2, name: "Rice", qty: 0.5, valueCents: 1 },
+  ]);
+  assert.equal(report.totalCents, 2);
+  assert.equal(report.totalCents, report.lines.reduce((sum, line) => sum + line.valueCents, 0));
+});
